import { useState } from "react";

function Form() {
  const [form, setForm] = useState({ ten: "", tuoi: "" });
  const doi = (e) =>
    setForm({ ...form, [e.target.name]: e.target.value });
  return (
    <form>
      <input name="ten" value={form.ten} onChange={doi} />
      <input name="tuoi" value={form.tuoi} onChange={doi} />
    </form>
  );
}

export default Form;
